CREATE TABLE procedure_versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),procedure_key TEXT NOT NULL,version INTEGER NOT NULL,intent TEXT NOT NULL,instructions TEXT NOT NULL,model TEXT NOT NULL,config_json TEXT NOT NULL,proposal_json TEXT NOT NULL DEFAULT '{}',created_by TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(project_id,procedure_key,version));
CREATE TRIGGER procedure_version_immutable BEFORE UPDATE ON procedure_versions BEGIN SELECT RAISE(ABORT,'Procedure versions are immutable'); END;
CREATE TABLE procedure_releases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),procedure_key TEXT NOT NULL,version_id TEXT NOT NULL REFERENCES procedure_versions(id),evaluation_id TEXT NOT NULL REFERENCES training_runs(id),cohort_limit INTEGER NOT NULL CHECK(cohort_limit BETWEEN 1 AND 100),state TEXT NOT NULL CHECK(state IN ('active','stopped')),approved_by TEXT NOT NULL,created_at INTEGER NOT NULL,stopped_at INTEGER);
CREATE UNIQUE INDEX procedure_one_active ON procedure_releases(project_id,procedure_key) WHERE state='active';
CREATE TABLE procedure_cohort(conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,project_id TEXT NOT NULL,release_id TEXT NOT NULL REFERENCES procedure_releases(id),created_at INTEGER NOT NULL,PRIMARY KEY(release_id,conversation_id));
CREATE TABLE procedure_generation(generation_id TEXT PRIMARY KEY REFERENCES ai_generations(id) ON DELETE CASCADE,release_id TEXT NOT NULL REFERENCES procedure_releases(id),version_id TEXT NOT NULL REFERENCES procedure_versions(id));
CREATE TABLE procedure_revocations(release_id TEXT NOT NULL REFERENCES procedure_releases(id),tool_name TEXT NOT NULL,revoked_by TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(release_id,tool_name));
CREATE TABLE procedure_reviews(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES procedure_versions(id),state TEXT NOT NULL CHECK(state IN ('approved','rejected')),reason TEXT NOT NULL,reviewer_id TEXT NOT NULL,created_at INTEGER NOT NULL);
